{
  "findings": [
    {
      "check_id": "CKV_AZURE_27",
      "title": "Email alerts to account administrators are disabled",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The policy does not enable email notifications to subscription service and co-administrators, which may prevent responsible administrators from receiving critical SQL security alerts."
    },
    {
      "check_id": "CKV_AZURE_25",
      "title": "SQL threat detection types are disabled",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The policy explicitly disables SQL injection and data exfiltration alerts, leaving significant database attack and data-loss activity undetected."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key\n  retention_days             = 20\n  email_addresses            = [\"securityengineer@bridgecrew.io\"]\n  email_account_admins       = true\n}\n",
  "fix_summary": "Removed the disabled alert types so all SQL threat detections remain active. Enabled security alert emails to subscription service and co-administrators."
}
